    int kde_mode_list_v2::deferred_destroy_global_func(void *data) {
        auto object = static_cast<kde_mode_list_v2 *>(data);
        wl_global_destroy(object->m_global);
        object->m_global = nullptr;
        wl_event_source_remove(object->m_globalRemovedEvent);
        object->m_globalRemovedEvent = nullptr;
        wl_list_remove(&object->m_displayDestroyedListener.link);
        object->kde_mode_list_v2_destroy_global();
        return 0;
    }

    kde_mode_list_v2::kde_mode_list_v2(struct ::wl_client *client, int id, int version)
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
        init(client, id, version);
    }

    kde_mode_list_v2::kde_mode_list_v2(struct ::wl_display *display, int version)
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
        init(display, version);
    }

    kde_mode_list_v2::kde_mode_list_v2(struct ::wl_resource *resource)
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
        init(resource);
    }

    kde_mode_list_v2::kde_mode_list_v2()
        : m_resource_map()
        , m_resource(nullptr)
        , m_global(nullptr)
        , m_display(nullptr)
        , m_globalRemovedEvent(nullptr)
    {
    }

    kde_mode_list_v2::~kde_mode_list_v2()
    {
        for (auto resource : std::as_const(m_resource_map))
            resource->kde_mode_list_v2_object = nullptr;

        if (m_resource)
            m_resource->kde_mode_list_v2_object = nullptr;

        if (m_global) {
            if (m_globalRemovedEvent)
                wl_event_source_remove(m_globalRemovedEvent);
            wl_global_destroy(m_global);
            wl_list_remove(&m_displayDestroyedListener.link);
        }
    }

    void kde_mode_list_v2::init(struct ::wl_client *client, int id, int version)
    {
        m_resource = bind(client, id, version);
    }

    void kde_mode_list_v2::init(struct ::wl_resource *resource)
    {
        m_resource = bind(resource);
    }

    kde_mode_list_v2::Resource *kde_mode_list_v2::add(struct ::wl_client *client, int version)
    {
        Resource *resource = bind(client, 0, version);
        m_resource_map.insert(client, resource);
        return resource;
    }

    kde_mode_list_v2::Resource *kde_mode_list_v2::add(struct ::wl_client *client, int id, int version)
    {
        Resource *resource = bind(client, id, version);
        m_resource_map.insert(client, resource);
        return resource;
    }

    kde_mode_list_v2::Resource *kde_mode_list_v2::add(struct ::wl_resource *resource)
    {
        return *m_resource_map.insert(wl_resource_get_client(resource), bind(resource));
    }

    void kde_mode_list_v2::init(struct ::wl_display *display, int version)
    {
        m_display = display;
        m_global = wl_global_create(display, &::kde_mode_list_v2_interface, version, this, bind_func);
        m_displayDestroyedListener.notify = kde_mode_list_v2::display_destroy_func;
        m_displayDestroyedListener.parent = this;
#ifdef HAVE_ACK_GLOBAL_REMOVE
        wl_global_set_withdrawn_listener(m_global, [](wl_global *global) {
            auto object = static_cast<kde_mode_list_v2 *>(wl_global_get_user_data(global));
            object->kde_mode_list_v2_destroy_global();
        });
#endif
        wl_display_add_destroy_listener(display, &m_displayDestroyedListener);
    }

    const struct wl_interface *kde_mode_list_v2::interface()
    {
        return &::kde_mode_list_v2_interface;
    }

    kde_mode_list_v2::Resource *kde_mode_list_v2::kde_mode_list_v2_allocate()
    {
        return new Resource;
    }

    void kde_mode_list_v2::kde_mode_list_v2_destroy_global()
    {
    }

    void kde_mode_list_v2::kde_mode_list_v2_bind_resource(Resource *)
    {
    }

    void kde_mode_list_v2::kde_mode_list_v2_destroy_resource(Resource *)
    {
    }

    void kde_mode_list_v2::bind_func(struct ::wl_client *client, void *data, uint32_t version, uint32_t id)
    {
        kde_mode_list_v2 *that = static_cast<kde_mode_list_v2 *>(data);
        that->add(client, id, version);
    }

    void kde_mode_list_v2::display_destroy_func(struct ::wl_listener *listener, void *data)
    {
        Q_UNUSED(data);
        kde_mode_list_v2 *that = static_cast<kde_mode_list_v2::DisplayDestroyedListener *>(listener)->parent;
        that->m_global = nullptr;
        that->m_globalRemovedEvent = nullptr;
    }

    void kde_mode_list_v2::destroy_func(struct ::wl_resource *client_resource)
    {
        Resource *resource = Resource::fromResource(client_resource);
        Q_ASSERT(resource);
        kde_mode_list_v2 *that = resource->kde_mode_list_v2_object;
        if (Q_LIKELY(that)) {
            that->m_resource_map.remove(resource->client(), resource);
            that->kde_mode_list_v2_destroy_resource(resource);

            that = resource->kde_mode_list_v2_object;
            if (that && that->m_resource == resource)
                that->m_resource = nullptr;
        }
        delete resource;
    }


    void kde_mode_list_v2::globalRemove()
    {
        if (!m_global || m_globalRemovedEvent)
            return;

        struct wl_event_loop *event_loop = wl_display_get_event_loop(m_display);
        m_globalRemovedEvent = wl_event_loop_add_timer(event_loop, deferred_destroy_global_func, this);
        wl_event_source_timer_update(m_globalRemovedEvent, 24 * 60 * 60 * 1000);

        wl_global_remove(m_global);
    }

    kde_mode_list_v2::Resource *kde_mode_list_v2::bind(struct ::wl_client *client, uint32_t id, int version)
    {
        Q_ASSERT_X(!wl_client_get_object(client, id), "QWaylandObject bind", QStringLiteral("binding to object %1 more than once").arg(id).toLocal8Bit().constData());
        struct ::wl_resource *handle = wl_resource_create(client, &::kde_mode_list_v2_interface, version, id);
        return bind(handle);
    }

    kde_mode_list_v2::Resource *kde_mode_list_v2::bind(struct ::wl_resource *handle)
    {
        Resource *resource = kde_mode_list_v2_allocate();
        resource->kde_mode_list_v2_object = this;

        wl_resource_set_implementation(handle, &m_kde_mode_list_v2_interface, resource, destroy_func);
        resource->handle = handle;
        kde_mode_list_v2_bind_resource(resource);
        return resource;
    }
    kde_mode_list_v2::Resource *kde_mode_list_v2::Resource::fromResource(struct ::wl_resource *resource)
    {
        if (Q_UNLIKELY(!resource))
            return nullptr;
        if (wl_resource_instance_of(resource, &::kde_mode_list_v2_interface, &m_kde_mode_list_v2_interface))
            return static_cast<Resource *>(wl_resource_get_user_data(resource));
        return nullptr;
    }

