    void kde_mode_list_v2::handle_destroy(
        ::wl_client *client,
        struct wl_resource *resource)
    {
        Q_UNUSED(client);
        Resource *qtResource = Resource::fromResource(resource);
        if (Q_UNLIKELY(!qtResource->kde_mode_list_v2_object)) {
            wl_resource_destroy(resource);
            return;
        }
        static_cast<kde_mode_list_v2 *>(qtResource->kde_mode_list_v2_object)->kde_mode_list_v2_destroy(
            qtResource);
    }

